/*
  4D Menger on S^3 (Parametric Visualization)
  -------------------------------------------
  - Each pixel (u,v) -> angles (alpha,beta).
  - Time (iTime) -> angle gamma.
  - We build (x,y,z,w) on the unit 3-sphere in R^4.
  - Check if that 4D point is in Menger set.
  - Output color accordingly.

  This is NOT a 3D raymarch. It's a 2D "map" of the 3-sphere,
  animated in time. Should look stable, without flicker, and
  reveal interesting fractal structure on S^3.
*/

#ifdef GL_ES
precision mediump float;
#endif



// --------------------------------------------------
// 4D Menger membership test: returns iteration
// at which we exit (0 if immediate). If we never
// exit by maxIter, return maxIter. You can then
// color based on the iteration or do a simple in/out.
//
// The "typical" approach is to do:
// 1) p *= 3
// 2) if( each coordinate in [1,2] ) => hole => exit
// 3) p = fract(p)
// repeat
// --------------------------------------------------
int menger4DIterations(in vec4 p) 
{
    // We'll do up to N iterations:
    const int N = 8;

    // optional shift from [-1,1] to [0,1], but
    // if you want a repeating pattern, you can skip or use fract
    // We'll do it once at the start:
    p = (p + 1.0)*0.5;  // now p is in [0,1]^4 if originally in [-1,1]^4
                       // S^3 is inside that domain, but not always fully.

    for(int i=1; i<=N; i++)
    {
        p *= 3.0;
        // check hole => if all in [1,2], it's out
        if( p.x>1.0 && p.x<2.0 &&
            p.y>1.0 && p.y<2.0 &&
            p.z>1.0 && p.z<2.0 &&
            p.w>1.0 && p.w<2.0 )
        {
            return i;  // exit iteration
        }
        // fract
        p = fract(p);
    }
    // Survived all => "in"
    return N;
}

// Helper: convert iteration to some color
vec3 iterationColor(int iter, int maxIter)
{
    if(iter >= maxIter) {
        // "fully in" after maxIter
        return vec3(0.0, 0.9, 0.7);
    } else {
        // out at iteration = iter
        float f = float(iter) / float(maxIter);
        // a simple gradient from red (early exit) to white
        return mix(vec3(1.0, 0.0, 0.2), vec3(1.0), f);
    }
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalized coords in [0,1]
    vec2 uv = fragCoord.xy / iResolution.xy;

    // angles from uv
    float alpha = 2.0*3.14159*uv.x; // [0..2*pi)
    float beta  = 3.14159*uv.y;    // [0..pi)

    // third angle from time
    float gamma = iTime*0.3;       // feel free to tweak speed

    // Param for S^3 (one possible choice):
    float sb = sin(beta);
    float cb = cos(beta);
    float sa = sin(alpha);
    float ca = cos(alpha);
    float sg = sin(gamma);
    float cg = cos(gamma);

    // (x,y,z,w) on S^3
    // We ensure x^2 + y^2 + z^2 + w^2 = 1.
    // This particular parameterization places
    // "beta" like a polar angle for x vs. the rest,
    // "alpha" as an azimuth for (y,z), and "gamma" rotates in (z,w).
    float x = cb;
    float y = sb*ca;
    float z = sb*sa*cg;
    float w = sb*sa*sg;

    // Evaluate fractal membership
    int iter = menger4DIterations(vec4(x,y,z,w));

    // Map iteration to color
    vec3 col = iterationColor(iter, 8);

    fragColor = vec4(col, 1.0);
}
